sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {
    var ciId = current.getValue('cmdb_ci');
    if (!ciId) return;

    var ciGr = new GlideRecord('x_2223823_apollo_0_cmdb_ci_medical_equipments');
    if(!ciGr.get(ciId)){
		return;
	}
    var newState = current.getValue('state');

    // 1. Moving to Implement (-1): Set equipment to Under Maintenance (2)
    if (newState == '-1' && previous.getValue('state') != '-1') {
        ciGr.setValue('operational_status', '3'); // 3 = Repair in progress
        ciGr.setValue('install_status', '3'); //3 = In Maintenance
        ciGr.update();
        gs.info('[BR-09] Equipment {0} set to Under Maintenance for Change {1}', ciGr.getDisplayValue('name'), current.getValue('number'));
    }

    // 2. Moving to Closed (3): Set equipment back to Operational (1) if closed successful
    else if (newState == '3' && previous.getValue('state') != '3') {
        var closeCode = current.getValue('close_code');
        // If successful or successful_issues, restore to Operational (1)
        if (closeCode == 'successful' || closeCode == 'successful_issues') {
            ciGr.setValue('operational_status', '1'); // 1 = Operational
            ciGr.setValue('install_status', '6'); // 6 = In Stock
            ciGr.update();
            gs.info('[BR-09] Equipment {0} restored to Operational after Change {1}', ciGr.getDisplayValue('name'), current.getValue('number'));
        }
    }

    // 3. Moving to Canceled (4) after having been in Implement: revert back to Operational
    else if (newState == '4' && previous.getValue('state') == '-1') {
        ciGr.setValue('operational_status', '1');
		ciGr.setValue('install_status', '6');
        ciGr.update();
    }
})(current, previous);
